// Clincoo Blog bundle extra2 2026-10-01
(function(){
  var extra = [
    {id:'bundle-import-bernama-agar-tree-shake',langs:{id:{title:'Pakai Import Bernama agar Tree-Shake Bundle Clincoo Berhasil',desc:'Import default dari barrel file sering menarik seluruh pustaka. Minta path fungsi yang sempit.',content:'<p class=\"mb-4\">Barrel index.js yang mengekspor semuanya membuat bundler di editor.clincoo.buzz kehilangan petunjuk mana yang dipakai.</p><p class=\"mb-4\">Ganti import DefaultLib dari paket besar dengan import { fungsiDipakai } dari subpath resmi.</p><p class=\"mb-4\">Setelah build pratinjau, cari nama fungsi yang tidak dipanggil di file hasil. Jika masih ada, tree-shake gagal.</p><p class=\"mb-4\">Tempel potongan import ke AI dan minta alternatif side-effect-free. Tolak saran yang menambahkan plugin bundler baru di commit yang sama.</p><p class=\"mb-4\">Catat pola import yang lolos budget di README app.clincoo.buzz dan contohnya di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Use Named Imports so Tree-Shaking the Clincoo Bundle Actually Works',desc:'A default import from a barrel file often pulls the whole library. Ask for a narrow function path.',content:'<p class=\"mb-4\">A barrel index.js that re-exports everything hides which symbols editor.clincoo.buzz actually uses.</p><p class=\"mb-4\">Replace a DefaultLib import from a large package with import { usedFn } from an official subpath.</p><p class=\"mb-4\">After a preview build, search the output for unused function names. If they remain, tree-shaking failed.</p><p class=\"mb-4\">Paste the import snippet to AI and ask for a side-effect-free alternative. Reject a new bundler plugin in the same commit.</p><p class=\"mb-4\">Record the import pattern that stays under budget in the app.clincoo.buzz README and link an example on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-jangan-pecah-chunk-terlalu-kecil',langs:{id:{title:'Jangan Pecah Chunk Bundle Clincoo sampai Terlalu Kecil',desc:'Seratus file 2 KB menambah handshake HTTP lebih mahal daripada satu file 40 KB.',content:'<p class=\"mb-4\">Dynamic import setiap tombol di editor.clincoo.buzz terdengar modern, tetapi waterfall request memperlambat LCP di jaringan lambat.</p><p class=\"mb-4\">Gabungkan modul yang selalu dibuka bersama. Pecah hanya layar yang jarang atau sangat berat.</p><p class=\"mb-4\">Di tab Network pratinjau, hitung jumlah JS di atas 1 KB. Jika puluhan file muncul sebelum first paint, mundur.</p><p class=\"mb-4\">Minta AI mengusulkan peta chunk, bukan menambahkan lazy() di setiap komponen.</p><p class=\"mb-4\">Simpan batas jumlah request awal di catatan rilis app.clincoo.buzz dan tautkan audit di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Do Not Split the Clincoo Bundle into Tiny Chunks',desc:'A hundred 2 KB files cost more HTTP handshakes than one 40 KB file.',content:'<p class=\"mb-4\">Dynamic-importing every button on editor.clincoo.buzz sounds modern, but a request waterfall slows LCP on a slow network.</p><p class=\"mb-4\">Keep modules that always load together in one chunk. Split only rare or very heavy screens.</p><p class=\"mb-4\">In the preview Network tab, count JS files above 1 KB. If dozens appear before first paint, roll back.</p><p class=\"mb-4\">Ask AI for a chunk map, not a lazy() wrapper on every component.</p><p class=\"mb-4\">Store an initial-request cap in the app.clincoo.buzz release note and link the audit on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-buang-kode-mati-sebelum-minify',langs:{id:{title:'Buang Kode Mati di Bundle Clincoo sebelum Minify',desc:'Minify mengecilkan huruf, bukan fitur yang tidak pernah dipanggil. Hapus dulu cabang mati.',content:'<p class=\"mb-4\">Flag lama dan helper uji sering tersisa di source editor.clincoo.buzz lalu lolos ke produksi karena masih diimpor.</p><p class=\"mb-4\">Cari export yang tidak diimpor siapa pun. Hapus file, bukan hanya komentari pemanggilan.</p><p class=\"mb-4\">Coverage di pratinjau menandai fungsi yang tidak pernah hijau. Itu kandidat hapus, bukan kandidat compress.</p><p class=\"mb-4\">Kirim daftar export yatim ke AI. Minta patch hapus per file, bukan rewrite folder.</p><p class=\"mb-4\">Ukur ulang transfer app.clincoo.buzz setelah cabang mati hilang. Catat delta di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Drop Dead Code from the Clincoo Bundle before You Minify',desc:'Minify shrinks letters, not features nobody calls. Delete dead branches first.',content:'<p class=\"mb-4\">Old flags and test helpers often linger in editor.clincoo.buzz source and ship because something still imports them.</p><p class=\"mb-4\">Find exports that nobody imports. Delete the file instead of commenting out the call.</p><p class=\"mb-4\">Coverage in preview marks functions that never turn green. Those are delete candidates, not compress candidates.</p><p class=\"mb-4\">Send the orphan export list to AI. Ask for a per-file delete patch, not a folder rewrite.</p><p class=\"mb-4\">Measure app.clincoo.buzz transfer again after dead branches are gone. Record the delta on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-gagalkan-ci-jika-budget-naik',langs:{id:{title:'Gagalkan CI Clincoo jika Budget Bundle Naik tanpa Alasan',desc:'Angka budget yang hanya ada di README akan dilanggar diam-diam. Pasang gerbang di pipeline.',content:'<p class=\"mb-4\">Setiap pull request ke app.clincoo.buzz harus membandingkan ukuran asset dengan baseline commit sebelumnya.</p><p class=\"mb-4\">Jika kenaikan di atas ambang (misalnya 10 KB gzip), CI merah sampai ada catatan alasan di deskripsi PR.</p><p class=\"mb-4\">Jangan andalkan Lighthouse manual di laptop. Jalankan cek ukuran di runner yang sama setiap kali.</p><p class=\"mb-4\">Jika AI menambahkan pustaka, minta dulu perkiraan delta byte. Tolak merge jika delta kosong.</p><p class=\"mb-4\">Publikasikan grafik budget di blog.clincoo.buzz supaya editor.clincoo.buzz tidak dianggap tanpa batas.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Fail Clincoo CI when the Bundle Budget Grows without a Reason',desc:'A budget that lives only in the README will be broken in silence. Put a gate in the pipeline.',content:'<p class=\"mb-4\">Every pull request to app.clincoo.buzz should compare asset size with the previous baseline commit.</p><p class=\"mb-4\">If growth is above a threshold (for example 10 KB gzip), CI stays red until the PR describes why.</p><p class=\"mb-4\">Do not rely on a manual Lighthouse run on a laptop. Run the size check on the same runner every time.</p><p class=\"mb-4\">If AI adds a library, ask for an estimated byte delta first. Reject the merge when the delta is missing.</p><p class=\"mb-4\">Publish the budget chart on blog.clincoo.buzz so editor.clincoo.buzz is not treated as unlimited.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}},
    {id:'bundle-baca-treemap-setelah-setiap-build',langs:{id:{title:'Baca Treemap Bundle Clincoo setelah Setiap Build Pratinjau',desc:'Angka total menyesatkan. Treemap menunjukkan pustaka mana yang tiba-tiba membesar.',content:'<p class=\"mb-4\">Nyalakan visualizer bundler di pratinjau editor.clincoo.buzz sekali per rilis, bukan hanya saat panik.</p><p class=\"mb-4\">Urutkan kotak dari yang terbesar. Periksa apakah ikon, locale, atau tema gelap ikut masuk entry utama.</p><p class=\"mb-4\">Bandingkan treemap sebelum dan sesudah perubahan satu fitur. Kotak baru tanpa tiket adalah regresi.</p><p class=\"mb-4\">Unggah cuplikan treemap ke AI dan minta tiga kandidat pecah atau ganti pustaka. Jangan minta ganti bundler.</p><p class=\"mb-4\">Simpan treemap ringkas di artefak CI app.clincoo.buzz dan tautkan pelajaran di blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Editor resmi Clincoo',source2:'Clincoo App',source3:'Clincoo Blog'},en:{title:'Read the Clincoo Bundle Treemap after Every Preview Build',desc:'A single total hides which library just ballooned. The treemap shows the box that grew.',content:'<p class=\"mb-4\">Turn on the bundler visualizer in the editor.clincoo.buzz preview once per release, not only during a panic.</p><p class=\"mb-4\">Sort boxes from largest. Check whether icons, locales, or dark theme leaked into the main entry.</p><p class=\"mb-4\">Compare the treemap before and after one feature. A new box without a ticket is a regression.</p><p class=\"mb-4\">Upload a treemap snapshot to AI and ask for three split or replace candidates. Do not ask to switch bundlers.</p><p class=\"mb-4\">Keep a compact treemap in the app.clincoo.buzz CI artifacts and link the lesson on blog.clincoo.buzz.</p>',source:'Clincoo',sourceUrl:'https://editor.clincoo.buzz/',sourceSnippet:'Official Clincoo editor',source2:'Clincoo App',source3:'Clincoo Blog'}}}
  ];
  function merge(){
    if (!window.countryDataFiles || !window.countryDataFiles['bundle']) { setTimeout(merge, 30); return; }
    var arr = window.countryDataFiles['bundle'].articles;
    var have = {};
    for (var i = 0; i < arr.length; i++) have[arr[i].id] = true;
    for (var j = 0; j < extra.length; j++) { if (!have[extra[j].id]) arr.push(extra[j]); }
  }
  merge();
})();
